  1→//! Cache revalidation for ETag and git strategies.
  2→
  3→use anyhow::Result;
  4→
  5→use super::{CacheEntry, CacheStore, ValidationResult};
  6→use crate::registry::fetch::{GitFetcher, HttpFetcher};
  7→
  8→/// Performs cache revalidation using ETag or git checking.
  9→pub struct CacheRevalidator<'a> {
 10→    store: &'a CacheStore,
 11→    http: HttpFetcher,
 12→    git: GitFetcher,
 13→}
 14→
 15→/// Result of revalidation.
 16→#[derive(Debug)]
 17→pub enum RevalidationResult {
 18→    /// Content unchanged, cache extended.
 19→    Unchanged,
 20→    /// Content changed, new content available.
 21→    Updated(String),
 22→    /// Revalidation failed (fallback to cache or error).
 23→    Failed(String),
 24→}
 25→
 26→impl<'a> CacheRevalidator<'a> {
 27→    /// Create a new revalidator.
 28→    pub fn new(store: &'a CacheStore, git_clone_dir: impl Into<std::path::PathBuf>) -> Self {
 29→        Self {
 30→            store,
 31→            http: HttpFetcher::new(),
 32→            git: GitFetcher::new(git_clone_dir),
 33→        }
 34→    }
 35→
 36→    /// Revalidate an entry using its ETag.
 37→    pub fn revalidate_etag(
 38→        &self,
 39→        url: &str,
 40→        entry: &mut CacheEntry,
 41→        new_ttl_seconds: u64,
 42→    ) -> Result<RevalidationResult> {
 43→        let etag = entry.metadata.etag.as_deref();
 44→
 45→        match self.http.fetch_if_changed(url, etag)? {
 46→            None => {
 47→                // 304 Not Modified - extend TTL
 48→                entry.metadata.expires_at =
 49→                    chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
 50→                self.store.update(entry)?;
 51→                Ok(RevalidationResult::Unchanged)
 52→            }
 53→            Some(response) => {
 54→                // Content changed - update cache
 55→                let content_path = self
 56→                    .store
 57→                    .content_path(&entry.source_id, &entry.template_name);
 58→                std::fs::write(&content_path, &response.content)?;
 59→
 60→                entry.metadata.etag = response.etag;
 61→                entry.metadata.size_bytes = response.content.len() as u64;
 62→                entry.metadata.cached_at = chrono::Utc::now();
 63→                entry.metadata.expires_at =
 64→                    chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
 65→                self.store.update(entry)?;
 66→
 67→                Ok(RevalidationResult::Updated(response.content))
 68→            }
 69→        }
 70→    }
 71→
 72→    /// Revalidate an entry using git commit comparison.
 73→    pub fn revalidate_git(
 74→        &self,
 75→        url: &str,
 76→        git_ref: Option<&str>,
 77→        entry: &mut CacheEntry,
 78→        new_ttl_seconds: u64,
 79→    ) -> Result<RevalidationResult> {
 80→        let current_sha = match &entry.metadata.commit_sha {
 81→            Some(sha) => sha.clone(),
 82→            None => {
 83→                // No SHA to compare, must re-fetch
 84→                return self.fetch_git(url, git_ref, entry, new_ttl_seconds);
 85→            }
 86→        };
 87→
 88→        let has_updates = self.git.has_updates(url, git_ref, &current_sha)?;
 89→
 90→        if has_updates {
 91→            self.fetch_git(url, git_ref, entry, new_ttl_seconds)
 92→        } else {
 93→            // No updates - extend TTL
 94→            entry.metadata.expires_at =
 95→                chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
 96→            self.store.update(entry)?;
 97→            Ok(RevalidationResult::Unchanged)
 98→        }
 99→    }
100→
101→    /// Fetch from git and update the cache entry.
102→    fn fetch_git(
103→        &self,
104→        url: &str,
105→        git_ref: Option<&str>,
106→        entry: &mut CacheEntry,
107→        new_ttl_seconds: u64,
108→    ) -> Result<RevalidationResult> {
109→        let result = self.git.fetch(url, git_ref)?;
110→
111→        // Copy content from cloned repo to cache
112→        let content_path = self
113→            .store
114→            .content_path(&entry.source_id, &entry.template_name);
115→
116→        // For git sources, we store a marker that the content is at the git path
117→        let content = format!("git-path:{}", result.local_path.display());
118→        std::fs::write(&content_path, &content)?;
119→
120→        entry.metadata.commit_sha = Some(result.commit_sha);
121→        entry.metadata.cached_at = chrono::Utc::now();
122→        entry.metadata.expires_at =
123→            chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
124→        self.store.update(entry)?;
125→
126→        Ok(RevalidationResult::Updated(content))
127→    }
128→}
129→
130→/// Check if a validation result needs revalidation.
131→pub fn needs_revalidation(result: &ValidationResult) -> bool {
132→    matches!(result, ValidationResult::NeedsRevalidation)
133→}
