  1→//! Template resolution from multiple sources.
  2→//!
  3→//! Resolution order (first match wins):
  4→//! 1. Project-local (.bivvy/templates/)
  5→//! 2. User-local (~/.bivvy/templates/)
  6→//! 3. Remote (by priority) - TODO in M11
  7→//! 4. Built-in
  8→
  9→use crate::config::schema::TemplateSource as TemplateSourceConfig;
 10→use crate::error::{BivvyError, Result};
 11→use crate::registry::builtin::BuiltinLoader;
 12→use crate::registry::local::LocalLoader;
 13→use crate::registry::remote::RemoteLoader;
 14→use crate::registry::template::{Template, TemplateSource};
 15→use std::collections::HashMap;
 16→use std::path::Path;
 17→
 18→/// Template registry that resolves templates from multiple sources.
 19→#[derive(Debug, Clone)]
 20→pub struct Registry {
 21→    builtin: BuiltinLoader,
 22→    local: LocalLoader,
 23→    remote: RemoteLoader,
 24→}
 25→
 26→impl Registry {
 27→    /// Create a new registry for a project (without remote sources).
 28→    pub fn new(project_root: Option<&Path>) -> Result<Self> {
 29→        Ok(Self {
 30→            builtin: BuiltinLoader::new()?,
 31→            local: LocalLoader::new(project_root)?,
 32→            remote: RemoteLoader::empty(),
 33→        })
 34→    }
 35→
 36→    /// Create a registry with remote template sources.
 37→    pub fn with_remote_sources(
 38→        project_root: Option<&Path>,
 39→        sources: &[TemplateSourceConfig],
 40→    ) -> Result<Self> {
 41→        let fetcher = crate::registry::fetch::HttpFetcher::new();
 42→        let cache_dir = crate::cache::default_cache_dir();
 43→        let cache = crate::cache::CacheStore::new(cache_dir);
 44→
 45→        let remote = RemoteLoader::new(sources, &fetcher, &cache).map_err(|e| {
 46→            BivvyError::ConfigValidationError {
 47→                message: format!("Failed to load remote templates: {}", e),
 48→            }
 49→        })?;
 50→
 51→        Ok(Self {
 52→            builtin: BuiltinLoader::new()?,
 53→            local: LocalLoader::new(project_root)?,
 54→            remote,
 55→        })
 56→    }
 57→
 58→    /// Create a registry with a pre-loaded remote loader (for testing).
 59→    #[cfg(test)]
 60→    pub(crate) fn with_remote_loader(
 61→        project_root: Option<&Path>,
 62→        remote: RemoteLoader,
 63→    ) -> Result<Self> {
 64→        Ok(Self {
 65→            builtin: BuiltinLoader::new()?,
 66→            local: LocalLoader::new(project_root)?,
 67→            remote,
 68→        })
 69→    }
 70→
 71→    /// Resolve a template by name.
 72→    ///
 73→    /// Resolution order (first match wins):
 74→    /// 1. Project-local (.bivvy/templates/)
 75→    /// 2. User-local (~/.bivvy/templates/)
 76→    /// 3. Remote (by priority)
 77→    /// 4. Built-in
 78→    pub fn resolve(&self, name: &str) -> Result<(&Template, TemplateSource)> {
 79→        // Check local first (includes both project and user)
 80→        if let Some((template, source)) = self.local.get_with_source(name) {
 81→            return Ok((template, source));
 82→        }
 83→
 84→        // Check remote sources
 85→        if let Some((template, priority)) = self.remote.get_with_priority(name) {
 86→            return Ok((template, TemplateSource::Remote { priority }));
 87→        }
 88→
 89→        // Check built-in
 90→        if let Some(template) = self.builtin.get(name) {
 91→            return Ok((template, TemplateSource::Builtin));
 92→        }
 93→
 94→        Err(BivvyError::UnknownTemplate {
 95→            name: name.to_string(),
 96→        })
 97→    }
 98→
 99→    /// Get a template by name (without source info).
100→    pub fn get(&self, name: &str) -> Option<&Template> {
101→        self.resolve(name).ok().map(|(t, _)| t)
102→    }
103→
104→    /// Check if a template exists.
105→    pub fn has(&self, name: &str) -> bool {
106→        self.local.has(name) || self.remote.has(name) || self.builtin.get(name).is_some()
107→    }
108→
109→    /// Get all available template names.
110→    pub fn all_template_names(&self) -> Vec<String> {
111→        let mut names: Vec<String> = self
112→            .builtin
113→            .template_names()
114→            .into_iter()
115→            .map(|s| s.to_string())
116→            .collect();
117→
118→        // Add remote templates
119→        for name in self.remote.template_names() {
120→            if !names.contains(&name.to_string()) {
121→                names.push(name.to_string());
122→            }
123→        }
124→
125→        // Add local templates (may override both remote and built-in)
126→        for name in self.local.template_names() {
127→            if !names.contains(&name.to_string()) {
128→                names.push(name.to_string());
129→            }
130→        }
131→
132→        names.sort();
133→        names
134→    }
135→
136→    /// Get templates in detection order for `bivvy init`.
137→    pub fn detection_order(&self) -> Vec<&Template> {
138→        // Start with built-in detection order
139→        self.builtin.detection_order()
140→    }
141→
142→    /// Get the builtin loader (for manifest access).
143→    pub fn builtin(&self) -> &BuiltinLoader {
144→        &self.builtin
145→    }
146→
147→    /// Validate inputs against a template's input contract.
148→    pub fn validate_inputs(
149→        &self,
150→        template_name: &str,
151→        inputs: &HashMap<String, serde_yaml::Value>,
152→    ) -> Result<Vec<String>> {
153→        let template = self
154→            .get(template_name)
155→            .ok_or_else(|| BivvyError::UnknownTemplate {
156→                name: template_name.to_string(),
157→            })?;
158→
159→        let mut errors = Vec::new();
160→
161→        // Check all required inputs are provided
162→        for (name, contract) in &template.inputs {
163→            if let Err(e) = contract.validate(name, inputs.get(name)) {
164→                errors.push(e);
165→            }
166→        }
167→
168→        // Check no unknown inputs are provided
169→        for key in inputs.keys() {
170→            if !template.inputs.contains_key(key) {
171→                errors.push(format!(
172→                    "Unknown input '{}' for template '{}'",
173→                    key, template_name
174→                ));
175→            }
176→        }
177→
178→        Ok(errors)
179→    }
180→
181→    /// Get effective input values (provided + defaults).
182→    pub fn effective_inputs(
183→        &self,
184→        template_name: &str,
185→        provided: &HashMap<String, serde_yaml::Value>,
186→    ) -> Result<HashMap<String, serde_yaml::Value>> {
187→        let template = self
188→            .get(template_name)
189→            .ok_or_else(|| BivvyError::UnknownTemplate {
190→                name: template_name.to_string(),
191→            })?;
192→
193→        let mut effective = HashMap::new();
194→
195→        for (name, contract) in &template.inputs {
196→            if let Some(value) = contract.effective_value(provided.get(name)) {
197→                effective.insert(name.clone(), value.clone());
198→            }
199→        }
200→
201→        Ok(effective)
202→    }
203→}
