  1→//! Remote template loading from HTTP sources.
  2→//!
  3→//! Fetches templates from HTTP URLs defined in `template_sources`
  4→//! and caches them using the shared cache infrastructure.
  5→
  6→use anyhow::{Context, Result};
  7→use std::collections::HashMap;
  8→
  9→use super::fetch::HttpFetcher;
 10→use super::template::Template;
 11→use crate::cache::{parse_ttl, CacheStore};
 12→use crate::config::schema::TemplateSource as TemplateSourceConfig;
 13→
 14→/// Loads templates from remote HTTP sources with caching.
 15→#[derive(Debug, Clone)]
 16→pub struct RemoteLoader {
 17→    /// Fetched and parsed templates, keyed by name.
 18→    templates: HashMap<String, (Template, u32)>,
 19→}
 20→
 21→impl RemoteLoader {
 22→    /// Create a new remote loader by fetching templates from the given sources.
 23→    pub fn new(
 24→        sources: &[TemplateSourceConfig],
 25→        fetcher: &HttpFetcher,
 26→        cache: &CacheStore,
 27→    ) -> Result<Self> {
 28→        let mut templates = HashMap::new();
 29→
 30→        for source in sources {
 31→            match Self::load_source(source, fetcher, cache) {
 32→                Ok(loaded) => {
 33→                    for template in loaded {
 34→                        // Only insert if not already present (higher priority wins)
 35→                        templates
 36→                            .entry(template.name.clone())
 37→                            .or_insert((template, source.priority));
 38→                    }
 39→                }
 40→                Err(e) => {
 41→                    tracing::warn!("Failed to load templates from {}: {}", source.url, e);
 42→                }
 43→            }
 44→        }
 45→
 46→        Ok(Self { templates })
 47→    }
 48→
 49→    /// Create an empty remote loader (no sources).
 50→    pub fn empty() -> Self {
 51→        Self {
 52→            templates: HashMap::new(),
 53→        }
 54→    }
 55→
 56→    /// Load templates from a single source.
 57→    fn load_source(
 58→        source: &TemplateSourceConfig,
 59→        fetcher: &HttpFetcher,
 60→        cache: &CacheStore,
 61→    ) -> Result<Vec<Template>> {
 62→        let source_id = format!("http:{}", source.url);
 63→
 64→        // Check cache first
 65→        if let Some(entry) = cache.load(&source_id, "_index")? {
 66→            if !entry.is_expired() {
 67→                let content = cache.read_content(&entry)?;
 68→                return Self::parse_templates(&content);
 69→            }
 70→        }
 71→
 72→        // Fetch from remote
 73→        let response = fetcher
 74→            .fetch(&source.url)
 75→            .with_context(|| format!("Failed to fetch template source: {}", source.url))?;
 76→
 77→        // Cache the response
 78→        let ttl_seconds = source
 79→            .cache
 80→            .as_ref()
 81→            .and_then(|c| parse_ttl(&c.ttl).ok())
 82→            .map(|d| d.num_seconds() as u64)
 83→            .unwrap_or(604800);
 84→        cache.store(&source_id, "_index", &response.content, ttl_seconds)?;
 85→
 86→        Self::parse_templates(&response.content)
 87→    }
 88→
 89→    /// Parse a YAML response containing one or more templates.
 90→    ///
 91→    /// Supports two formats:
 92→    /// 1. A single template YAML document
 93→    /// 2. A YAML array of templates
 94→    fn parse_templates(content: &str) -> Result<Vec<Template>> {
 95→        // Try parsing as a list first
 96→        if let Ok(templates) = serde_yaml::from_str::<Vec<Template>>(content) {
 97→            return Ok(templates);
 98→        }
 99→
100→        // Try as a single template
101→        if let Ok(template) = serde_yaml::from_str::<Template>(content) {
102→            return Ok(vec![template]);
103→        }
104→
105→        anyhow::bail!(
106→            "Remote source returned content that is neither a template nor a list of templates"
107→        )
108→    }
109→
110→    /// Get a template by name.
111→    pub fn get(&self, name: &str) -> Option<&Template> {
112→        self.templates.get(name).map(|(t, _)| t)
113→    }
114→
115→    /// Get a template with its priority.
116→    pub fn get_with_priority(&self, name: &str) -> Option<(&Template, u32)> {
117→        self.templates.get(name).map(|(t, p)| (t, *p))
118→    }
119→
120→    /// Check if a template exists.
121→    pub fn has(&self, name: &str) -> bool {
122→        self.templates.contains_key(name)
123→    }
124→
125→    /// Get all template names.
126→    pub fn template_names(&self) -> Vec<&str> {
127→        self.templates.keys().map(|s| s.as_str()).collect()
128→    }
129→}
