174→/// Authentication header for remote fetching.
175→#[derive(Debug, Clone)]
176→pub struct AuthHeader {
177→    /// Header name (e.g., "Authorization").
178→    pub header_name: String,
179→    /// Header value (e.g., "Bearer token123").
180→    pub header_value: String,
181→}
182→
183→impl AuthHeader {
184→    /// Create a Bearer token auth header.
185→    pub fn bearer(token: &str) -> Self {
186→        Self {
187→            header_name: "Authorization".to_string(),
188→            header_value: format!("Bearer {}", token),
189→        }
190→    }
191→
192→    /// Create a custom header auth.
193→    pub fn custom(name: impl Into<String>, value: impl Into<String>) -> Self {
194→        Self {
195→            header_name: name.into(),
196→            header_value: value.into(),
197→        }
198→    }
199→}
200→
201→/// Resolves authentication from config settings.
202→pub fn resolve_auth(
203→    auth_type: &str,
204→    token_env: &str,
205→    header: Option<&str>,
206→    env_vars: &HashMap<String, String>,
207→) -> Option<AuthHeader> {
208→    // First check the provided env_vars map, then fall back to system env
209→    let token = env_vars
210→        .get(token_env)
211→        .cloned()
212→        .or_else(|| std::env::var(token_env).ok())?;
213→
214→    match auth_type {
215→        "bearer" => Some(AuthHeader::bearer(&token)),
216→        "header" => {
217→            let header_name = header.unwrap_or("X-Auth-Token");
218→            Some(AuthHeader::custom(header_name, &token))
219→        }
220→        _ => None,
221→    }
222→}
