    #[test]
    fn concurrent_store_does_not_corrupt_cache() {
        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();

        let handles: Vec<_> = (0..8)
            .map(|i| {
                let root = root.clone();
                std::thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    let content = format!("content-from-thread-{}", i);
                    store
                        .store("http:test", "shared-key", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        let store = CacheStore::new(&root);
        let entry = store.load("http:test", "shared-key").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();

        // Content must be one of the valid values, not a corrupted mix
        assert!(
            content.starts_with("content-from-thread-"),
            "content was corrupted: {:?}",
            content
        );
        // Metadata size must match actual content
        assert_eq!(entry.metadata.size_bytes, content.len() as u64);
    }

    #[test]
    fn concurrent_store_different_keys_no_corruption() {
        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();

        let handles: Vec<_> = (0..8)
            .map(|i| {
                let root = root.clone();
                std::thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    let key = format!("template-{}", i);
                    let content = format!("content-{}", i);
                    store.store("http:test", &key, &content, 3600).unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        let store = CacheStore::new(&root);
        for i in 0..8 {
            let key = format!("template-{}", i);
            let expected = format!("content-{}", i);
            let entry = store.load("http:test", &key).unwrap().unwrap();
            let content = store.read_content(&entry).unwrap();
            assert_eq!(content, expected);
        }
    }

    #[test]
    fn write_content_stores_data_at_content_path() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());
        store.ensure_dir().unwrap();

        store
            .write_content("http:test", "template", "hello world")
            .unwrap();

        let path = store.content_path("http:test", "template");
        let content = std::fs::read_to_string(path).unwrap();
        assert_eq!(content, "hello world");
    }

    #[test]
    fn no_temp_files_left_after_store() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template", "content", 3600)
            .unwrap();

        // No .tmp files should remain
        for entry in std::fs::read_dir(temp.path()).unwrap() {
            let path = entry.unwrap().path();
            let name = path.file_name().unwrap().to_string_lossy();
            assert!(
                !name.ends_with(".tmp"),
                "temp file left behind: {:?}",
                path
            );
        }
    }
}

