    self.content_path(source_id, template_name)
        .with_extension("lock")
}

/// Acquire an exclusive lock for a cache entry.
///
/// Returns a [`File`] handle that holds the lock. The lock is released
/// when the handle is dropped.
fn lock_entry(&self, source_id: &str, template_name: &str) -> Result<File> {
    self.ensure_dir()?;
    let lock_path = self.lock_path(source_id, template_name);
    let lock_file = OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(false)
        .open(&lock_path)
        .with_context(|| format!("Failed to open lock file {:?}", lock_path))?;
    lock_file
        .lock_exclusive()
        .with_context(|| format!("Failed to acquire lock on {:?}", lock_path))?;
    Ok(lock_file)
}

/// Write data to a path atomically via a temporary file and rename.
fn atomic_write(path: &Path, data: &[u8]) -> Result<()> {
    let tmp_path = path.with_extension("tmp");
    fs::write(&tmp_path, data)
        .with_context(|| format!("Failed to write temp file {:?}", tmp_path))?;
    fs::rename(&tmp_path, path)
        .with_context(|| format!("Failed to rename {:?} to {:?}", tmp_path, path))?;
    Ok(())
}

/// Store content and return a cache entry.
///
/// Uses file locking and atomic writes to prevent corruption from
/// concurrent access.
pub fn store(
    &self,
    source_id: &str,
    template_name: &str,
    content: &str,
    ttl_seconds: u64,
) -> Result<CacheEntry> {
    let _lock = self.lock_entry(source_id, template_name)?;

    let content_path = self.content_path(source_id, template_name);
    Self::atomic_write(&content_path, content.as_bytes())?;

    let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
        .with_size(content.len() as u64);

    self.save_metadata_locked(&entry)?;

    Ok(entry)
}

/// Write content to the cache for an entry.
///
/// This acquires the entry lock and performs an atomic write. Use this
/// instead of writing to the content path directly.
pub fn write_content(
    &self,
    source_id: &str,
    template_name: &str,
    content: &str,
) -> Result<()> {
    let _lock = self.lock_entry(source_id, template_name)?;
    let content_path = self.content_path(source_id, template_name);
    Self::atomic_write(&content_path, content.as_bytes())
}

/// Load a cached entry's metadata.
pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
    let meta_path = self.metadata_path(source_id, template_name);

    if !meta_path.exists() {
        return Ok(None);
    }

    let json = fs::read_to_string(&meta_path)?;
    let entry: CacheEntry = serde_json::from_str(&json)?;

    Ok(Some(entry))
}

/// Read the cached content.
pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
    fs::read_to_string(&entry.content_path).with_context(|| {
        format!(
            "Failed to read cached content from {:?}",
            entry.content_path
        )
    })
}

/// Save entry metadata while the entry lock is already held.
fn save_metadata_locked(&self, entry: &CacheEntry) -> Result<()> {
    let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
    let json = serde_json::to_string_pretty(entry)?;
    Self::atomic_write(&meta_path, json.as_bytes())
}

/// Update an entry's metadata (e.g., after revalidation).
///
/// Acquires the entry lock and writes metadata atomically.
pub fn update(&self, entry: &CacheEntry) -> Result<()> {
    let _lock = self.lock_entry(&entry.source_id, &entry.template_name)?;
    self.save_metadata_locked(entry)
}

/// Remove a cached entry.
pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
    let _lock = self.lock_entry(source_id, template_name)?;

    let content_path = self.content_path(source_id, template_name);
    let meta_path = self.metadata_path(source_id, template_name);

    let mut removed = false;

    if content_path.exists() {
        fs::remove_file(&content_path)?;
        removed = true;
    }

    if meta_path.exists() {
        fs::remove_file(&meta_path)?;
        removed = true;
    }

    Ok(removed)
}

